<script setup lang="ts">
definePageMeta({middleware:'auth'});useHead({title:'جزئیات سفارش'});const route=useRoute(),{api}=useShopApi();const{data:o,refresh}=await useAsyncData(`order-${route.params.id}`,()=>api<any>(`/profile/orders/${route.params.id}`));const money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v),steps=['pending','confirmed','processing','shipped','delivered'],labels:any={pending:'ثبت سفارش',confirmed:'تأیید پرداخت',processing:'آماده‌سازی',shipped:'ارسال‌شده',delivered:'تحویل‌شده'};const returnOpen=ref(false),sending=ref(false),message=ref(''),form=reactive({reason:'damaged',description:'',items:{} as Record<number,{selected:boolean,quantity:number,condition:string}>});watch(o,value=>{for(const item of value?.items||[])form.items[item.id]={selected:false,quantity:1,condition:'unopened'}},{immediate:true});async function submitReturn(){const items=Object.entries(form.items).filter(([,v])=>v.selected).map(([id,v])=>({order_item_id:Number(id),quantity:v.quantity,condition:v.condition}));if(!items.length){message.value='حداقل یک کالا را انتخاب کنید.';return}sending.value=true;try{await api(`/profile/orders/${o.value.id}/returns`,{method:'POST',body:{reason:form.reason,description:form.description||undefined,items}});message.value='درخواست مرجوعی با موفقیت ثبت شد.';returnOpen.value=false;await refresh()}catch(e:any){message.value=e?.data?.message||'ثبت درخواست انجام نشد.'}finally{sending.value=false}}
</script>
<template><div v-if="o" class="mx-auto max-w-5xl px-4 py-10"><div class="flex justify-between"><div><p class="text-sm text-slate-400">جزئیات سفارش</p><h1 class="mt-2 text-xl font-black">{{o.number}}</h1></div><NuxtLink to="/profile/orders" class="text-sm font-bold text-brand-700">بازگشت</NuxtLink></div><section class="mt-7 rounded-2xl border bg-white p-6"><div class="grid grid-cols-5 gap-2"><div v-for="(s,i) in steps" :key="s" class="text-center"><div :class="['mx-auto grid size-9 place-items-center rounded-full text-sm font-black',steps.indexOf(o.status)>=i?'bg-brand-700 text-white':'bg-slate-100 text-slate-400']">{{i+1}}</div><p class="mt-2 text-xs">{{labels[s]}}</p></div></div></section><section class="mt-5 rounded-2xl border bg-white p-5"><h2 class="font-black">کالاهای سفارش</h2><div class="mt-4 divide-y"><div v-for="item in o.items" :key="item.id" class="flex justify-between gap-4 py-4"><div><p class="font-bold">{{item.title}}</p><p class="mt-1 text-xs text-slate-400">{{Object.values(item.attributes||{}).filter(Boolean).join(' / ')}} • تعداد {{item.quantity}}</p></div><p class="shrink-0 font-black">{{money(item.total)}} تومان</p></div></div></section><section class="mt-5 grid gap-5 md:grid-cols-2"><div class="rounded-2xl border bg-white p-5"><h2 class="font-black">نشانی تحویل</h2><p class="mt-3 text-sm leading-7 text-slate-500">{{o.address_snapshot.province}}، {{o.address_snapshot.city}}، {{o.address_snapshot.address}}</p><p class="mt-2 text-xs text-slate-400">{{o.address_snapshot.receiver_name}} • {{o.address_snapshot.receiver_mobile}}</p></div><div class="rounded-2xl border bg-white p-5 text-sm"><div class="flex justify-between"><span>جمع کالاها</span><span>{{money(o.subtotal)}} تومان</span></div><div class="mt-3 flex justify-between text-emerald-700"><span>تخفیف</span><span>− {{money(o.discount_amount)}} تومان</span></div><div class="mt-3 flex justify-between"><span>ارسال</span><span>{{money(o.shipping_amount)}} تومان</span></div><div class="mt-4 flex justify-between border-t pt-4 text-base font-black"><span>مبلغ نهایی</span><span>{{money(o.payable_amount)}} تومان</span></div></div></section><section v-if="o.status==='delivered'" class="mt-5 rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-black">مرجوعی کالا</h2><p class="mt-1 text-sm text-slate-400">تا هفت روز پس از تحویل می‌توانید درخواست خود را ثبت کنید.</p></div><button v-if="!o.active_returns_count" class="rounded-xl border border-rose-200 px-4 py-2 text-sm font-bold text-rose-700" @click="returnOpen=!returnOpen">ثبت درخواست مرجوعی</button><span v-else class="rounded-xl bg-amber-50 px-4 py-2 text-sm font-bold text-amber-700">درخواست شما در حال پیگیری است</span></div><p v-if="message" class="mt-3 text-sm text-brand-700">{{message}}</p><form v-if="returnOpen" class="mt-5 border-t pt-5" @submit.prevent="submitReturn"><label class="text-sm font-bold">دلیل درخواست<select v-model="form.reason" class="mt-2 h-11 w-full rounded-xl border px-3"><option value="damaged">کالا آسیب‌دیده است</option><option value="wrong_item">کالای اشتباه ارسال شده</option><option value="not_as_described">با توضیحات مغایرت دارد</option><option value="quality">کیفیت مناسب نیست</option><option value="other">سایر موارد</option></select></label><div class="mt-5 space-y-3"><label v-for="item in o.items" :key="item.id" class="grid gap-3 rounded-xl border p-4 sm:grid-cols-[1fr_100px_150px]"><span class="flex items-center gap-2 font-bold"><input v-model="form.items[item.id].selected" type="checkbox" class="accent-brand-700">{{item.title}}</span><input v-model.number="form.items[item.id].quantity" type="number" min="1" :max="item.quantity" class="h-10 rounded-lg border px-2"><select v-model="form.items[item.id].condition" class="h-10 rounded-lg border px-2 text-sm"><option value="unopened">بازنشده</option><option value="opened">بازشده</option><option value="damaged">آسیب‌دیده</option></select></label></div><textarea v-model="form.description" rows="3" class="mt-4 w-full rounded-xl border p-3" placeholder="توضیحات تکمیلی…"/><button :disabled="sending" class="mt-3 rounded-xl bg-brand-700 px-6 py-3 font-bold text-white">{{sending?'در حال ثبت…':'ارسال درخواست'}}</button></form></section></div></template>
